# Hypothesis 2: A cell becomes 5 if it lies on a horizontal or vertical line segment
# connecting any TWO anchor points

anchors = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]

def cells_on_segments(anchors):
    """Return set of all cells lying on horiz/vert segments between any pair of anchors"""
    result = set()
    for i, a1 in enumerate(anchors):
        for j, a2 in enumerate(anchors):
            if i >= j:
                continue
            r1, c1 = a1
            r2, c2 = a2

            # Vertical segment (same column)
            if c1 == c2:
                min_r, max_r = min(r1, r2), max(r1, r2)
                for r in range(min_r, max_r + 1):
                    result.add((r, c1))

            # Horizontal segment (same row)
            if r1 == r2:
                min_c, max_c = min(c1, c2), max(c1, c2)
                for c in range(min_c, max_c + 1):
                    result.add((r1, c))

    return result

