def fill_rectangles(anchors):
    """Fill all cells within bounding box of ANY pair of anchors"""
    result = set()

    # For each pair
    for i, a1 in enumerate(anchors):
        for j, a2 in enumerate(anchors):
            if i >= j:
                continue
            r1, c1 = a1
            r2, c2 = a2

            # Bounding box between them
            rr_min, rr_max = min(r1, r2), max(r1, r2)
            cc_min, cc_max = min(c1, c2), max(c1, c2)

            for r in range(rr_min, rr_max + 1):
                for c in range(cc_min, cc_max + 1):
                    if (r, c) not in anchors:
                        result.add((r, c))

    return result

