# Hypothesis 7: For each pair of anchors sharing the SAME row OR column,
# fill all cells on the segment connecting them (exclusive of anchors themselves)

def fill_line_segments(anchors):
    """Fill horizontal/vertical segments between anchors on same line"""
    result = set()

    # Group by row
    by_row = {}
    for r, c in anchors:
        by_row.setdefault(r, []).append(c)

    for r, cols in by_row.items():
        cols_sorted = sorted(cols)
        for i in range(len(cols_sorted)):
            for j in range(i + 1, len(cols_sorted)):
                c1, c2 = cols_sorted[i], cols_sorted[j]
                # Fill horizontal segment between c1 and c2
                for c in range(c1 + 1, c2):
                    if (r, c) not in anchors:
                        result.add((r, c))

    # Group by column
    by_col = {}
    for r, c in anchors:
        by_col.setdefault(c, []).append(r)

    for c, rows in by_col.items():
        rows_sorted = sorted(rows)
        for i in range(len(rows_sorted)):
            for j in range(i + 1, len(rows_sorted)):
                r1, r2 = rows_sorted[i], rows_sorted[j]
                # Fill vertical segment between r1 and r2
                for r in range(r1 + 1, r2):
                    if (r, c) not in anchors:
                        result.add((r, c))

    return result

