# Hypothesis 9: For each PAIR of anchors, create an L-shaped path between them
# An L-shape goes horizontally from first anchor to its column matching second, then vertically to second
# Or alternatively: go vertically then horizontally
# The cells along BOTH paths get filled (except the anchors themselves)

def fill_L_paths(anchors):
    """Fill cells on L-shaped paths between any pair of anchors"""
    result = set()

    for i, a1 in enumerate(anchors):
        for j, a2 in enumerate(anchors):
            if i >= j:
                continue

            r1, c1 = a1
            r2, c2 = a2

            # Path 1: Horizontal then vertical (go to column c2 first, then row r2)
            # Horizontal segment from (r1, c1) to (r1, c2)
            for c in range(min(c1, c2) + 1, max(c1, c2)):
                result.add((r1, c))
            # Vertical segment from (r1, c2) to (r2, c2)
            for r in range(min(r1, r2) + 1, max(r1, r2)):
                result.add((r, c2))

            # Path 2: Vertical then horizontal (go to row r2 first, then column c2)
            # Vertical segment from (r1, c1) to (r2, c1)
            for r in range(min(r1, r2) + 1, max(r1, r2)):
                result.add((r, c1))
            # Horizontal segment from (r2, c1) to (r2, c2)
            for c in range(min(c1, c2) + 1, max(c1, c2)):
                result.add((r2, c))

    return result

