# Count anchors seen by each extra cell
def count_anchors_seen(cell, anchors):
    h_seen, v_seen = 0, 0
    r, c = cell
    # Horizontal
    for a in anchors:
        if r == a[0]:
            has_blocker = False
            for other_a in anchors:
                if other_a != a and r == other_a[0]:
                    if min(a[1], other_a[1]) < c < max(a[1], other_a[1]):
                        has_blocker = True
                        break
            if not has_blocker:
                h_seen += 1
                break  # Just need one
    # Vertical
    for a in anchors:
        if c == a[1]:
            has_blocker = False
            for other_a in anchors:
                if other_a[1] != a[1] and c == other_a[1]:
                    if min(a[0], other_a[0]) < r < max(a[0], other_a[0]):
                        has_blocker = True
                        break
            if not has_blocker:
                v_seen += 1
                break
    return h_seen + v_seen

print("\n\nAnchor count analysis for extra cells:")
for cell in extra_cells[:20]:
    cnt = count_anchors_seen(cell, anchors)
    print(f"  {cell}: sees {cnt} anchors")

# New hypothesis: A cell fills if:
# 1. It has a clear horizontal OR vertical line to an anchor, AND
# 2. It is NOT in an anchor row OR anchor col

anchors = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]
h, w = 13, 6

def has_clear_line_to_anchor(cell):
    r, c = cell
    for a in anchors:
        # Horizontal check
        if r == a[0]:
            blocker = False
            for other_a in anchors:
                if other_a != a and r == other_a[0]:
                    if min(a[1], other_a[1]) < c < max(a[1], other_a[1]):
                        blocker = True
                        break
            if not blocker:
                return True
        # Vertical check
        if c == a[1]:
            blocker = False
            for other_a in anchors:
                if other_a[1] != a[1] and c == other_a[1]:
                    if min(a[0], other_a[0]) < r < max(a[0], other_a[0]):
                        blocker = True
                        break
            if not blocker:
                return True
    return False

anchor_rows = set(a[0] for a in anchors)
anchor_cols = set(a[1] for a in anchors)

def is_in_anchor_row_or_col(cell):
    r, c = cell
    return r in anchor_rows or c in anchor_cols

clear_cells = [c for c in product(range(h), range(w)) if has_clear_line_to_anchor(c)]
non_anchor_cells = [c for c in clear_cells if not is_in_anchor_row_or_col(c)]

print(f"Clear cells: {len(clear_cells)}")
print(f"Non-anchor-position cells: {len(non_anchor_cells)}")

missing = filled_demo - set(non_anchor_cells)
extra = set(non_anchor_cells) - filled_demo
print(f"\nMissing: {sorted(missing)}")
print(f"Extra: {sorted(extra)}")

# New idea: Fill a cell if BOTH its row and its column have at least one anchor visible somewhere
# Meaning: the entire row can reach an anchor horizontally, AND entire col can reach vertically

anchors = [(0, 0), (3, 1), (3, 5), (11, 5), (12, 2)]
h, w = 13, 6

# For each row, check if any cell in that row has clear horizontal path to anchor
row_can_reach_anchor = []
for r in range(h):
    can_reach = False
    for c in range(w):
        for a in anchors:
            if r == a[0]:
                # Check if (r,c) can see this anchor horizontally
                blocker = False
                for other_a in anchors:
                    if other_a != a and r == other_a[0]:
                        if min(a[1], other_a[1]) < c < max(a[1], other_a[1]):
                            blocker = True
                            break
                if not blocker:
                    can_reach = True
                    break
    row_can_reach_anchor.append(can_reach)

# For each col, check if any cell in that col has clear vertical path to anchor  
col_can_reach_anchor = []
for c in range(w):
    can_reach = False
    for r in range(h):
        for a in anchors:
            if c == a[1]:
                blocker = False
                for other_a in anchors:
                    if other_a[1] != a[1] and c == other_a[1]:
                        if min(a[0], other_a[0]) < r < max(a[0], other_a[0]):
                            blocker = True
                            break
                if not blocker:
                    can_reach = True
                    break
    col_can_reach_anchor.append(can_reach)

print("Row can reach anchor:", row_can_reach_anchor)
print("Col can reach anchor:", col_can_reach_anchor)

# Cells where both row and col can reach anchor
both_cells = set()
for r in range(h):
    for c in range(w):
        if row_can_reach_anchor[r] and col_can_reach_anchor[c]:
